    if v_j is null or (v_j->>'attempts')::bigint <> v_r.att or (v_j->>'xp')::bigint <> v_r.xp or (v_j->>'spent_ms')::bigint <> v_r.spent
       or (v_j->>'units_max')::bigint < v_r.units or (v_j->>'returned_max')::bigint < v_r.ret then
